const suite={sensorId:'gps',sensorStep:0,sensorDraft:{transport:'NMEA 2000',device:'Multi-sensor gateway',name:'Cockpit depth',signal:'Depth',endpoint:'can0',priority:'Secondary',offset:0},sensorDiscovery:false,sensorError:false,installerStep:0,installDetected:false,installScenario:'supported',installLicense:false,installOptions:[true,true,true,true],installPath:'C:\\Program Files\\OpenNav X',installProgress:0,installBusy:false,installed:true,setupStep:0,setupDraft:{name:state.vessel,draft:state.draftDepth,safety:state.safetyDepth,capacity:state.capacity,reserve:state.reserve,units:'Nautical',theme:'day'},maintenance:'Repair',maintenanceStep:0,maintenanceBusy:false,updateChannel:'Stable',updateStatus:'idle',updateVersion:'0.6.0',snapshots:[],backupSelection:{settings:true,vessel:true,sensors:true,routes:true},restoreDraft:null,diagnosticTab:'Overview',guide:'installation',helpQuery:'',packId:'se-east',adapter:'Auto detect',recordStart:0,adapterTimeout:3,adapterConnection:'NMEA 2000 gateway',displayScale:'100%',layout:'Balanced',alarm:{cpa:.5,tcpa:15,depth:3.5,energy:25,sound:true,gps:true,anchor:true},preferences:{route:'Coastal',corridor:.15,orientation:'North up'},plugins:[{name:'Radar adapter',state:true},{name:'Dashboard instruments',state:true},{name:'Weather GRIB',state:false}],sensors:[{id:'gps',name:'GNSS receiver',signal:'GPS',transport:'NMEA 2000',endpoint:'can0 · 35',priority:'Primary',status:'Current',age:'0.2 s',rate:'5 Hz',pgn:'129029',offset:0},{id:'heading',name:'Heading compass',signal:'Heading',transport:'NMEA 2000',endpoint:'can0 · 36',priority:'Primary',status:'Current',age:'0.1 s',rate:'10 Hz',pgn:'127250',offset:0},{id:'depth',name:'Depth transducer',signal:'Depth',transport:'NMEA 2000',endpoint:'can0 · 44',priority:'Primary',status:'Current',age:'0.5 s',rate:'2 Hz',pgn:'128267',offset:0},{id:'wind',name:'Masthead wind',signal:'Wind',transport:'NMEA 2000',endpoint:'can0 · 45',priority:'Primary',status:'Current',age:'0.4 s',rate:'2 Hz',pgn:'130306',offset:0},{id:'motor',name:'Electric propulsion',signal:'Motor',transport:'Signal K',endpoint:'vessel.local:3000',priority:'Primary',status:'Current',age:'0.5 s',rate:'2 Hz',pgn:'propulsion.main',offset:0},{id:'battery',name:'House & propulsion battery',signal:'Battery',transport:'NMEA 2000',endpoint:'can0 · 51',priority:'Primary',status:'Current',age:'0.8 s',rate:'1 Hz',pgn:'127508',offset:0},{id:'rudder',name:'Rudder position',signal:'Rudder',transport:'NMEA 2000',endpoint:'can0 · 48',priority:'Primary',status:'Current',age:'0.3 s',rate:'3 Hz',pgn:'127245',offset:0},{id:'ais',name:'AIS receiver',signal:'AIS',transport:'NMEA 0183',endpoint:'COM4 · 38400 baud',priority:'Primary',status:'Current',age:'2 s',rate:'0.5 Hz',pgn:'!AIVDM',offset:0}],charts:[{id:'se-east',name:'Swedish east coast',format:'Vector ENC',edition:'2026.08',size:'186 MB',status:'Ready',region:'Östergötland · St. Anna · Arkösund'},{id:'baltic',name:'Baltic overview',format:'Raster BSB',edition:'2025.11',size:'42 MB',status:'Update available',region:'Baltic Sea · overview'}]};
const suiteLink=(label,detail,action,ico='chevron')=>`<button class="suite-link" data-action="${action}"><span class="suite-link-icon">${icon(ico)}</span><span><b>${label}</b><small>${detail}</small></span>${icon('chevron')}</button>`;
const selectField=(label,id,values,value)=>`<label class="field">${label}<select id="${id}">${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const summaryCard=(title,copy,ico='check')=>`<div class="summary-card">${icon(ico)}<div><b>${title}</b><p>${copy}</p></div></div>`;
const formError=()=>'<p id="formError" class="form-error" role="alert" hidden></p>';
function invalid(message){const error=$('#formError');if(error){error.hidden=false;error.textContent=message;error.scrollIntoView({block:'nearest'});}else toast(message);}
function settingLinks(){switch(state.settingsTab){
 case 'Navigation':return `${selectField('Distance & speed','navUnits',['Nautical','Metric'],state.units)}${selectField('Route preference','routePreference',['Coastal','Shortest passage','Avoid restricted areas'],suite.preferences.route)}${field('Route corridor · nm','routeCorridor',suite.preferences.corridor,'number','min="0.05" max="2" step="0.05"')}${button('Save navigation preferences','saveNavigation','full primary')}${suiteLink('Chart presentation','Layers, orientation and the radar overlay','showLayers','layers')}${suiteLink('Chart symbols & seamarks','Bilingual guide and the complete symbol atlas','showSymbols','chart')}${suiteLink('Charts & coverage','Installed charts, imports and licenses','showCharts','chart')}${suiteLink('Alarms & thresholds','Traffic, depth, energy and source loss','showAlarms','bell')}${suiteLink('Passage library','Routes, waypoints, tracks and GPX','showLibrary','route')}`;
 case 'Sensors':return `<div class="settings-intro"><span class="eyebrow">CONNECTED TO YOUR BOAT</span><h3>Every signal has a source.</h3><p>Connect, assign and verify each measurement before putting it on your helm.</p></div>${suiteLink('Manage sensors',suite.sensors.length+' configured sources · per-signal quality','showSensors','gauge')}${suiteLink('Add a sensor','NMEA 2000, NMEA 0183 or Signal K','addSensor','plus')}${suiteLink('Source health','Freshness, cadence and dropout states','showHealth','shield')}`;
 case 'Autopilot':return `${row('Adapter',suite.adapter==='Auto detect'?'Generic heading adapter':esc(suite.adapter))}${row('Control',state.apEnabled?'Enabled for preview':'Off by default')}${suiteLink('Adapter & capabilities','Connection, acknowledgement and supported modes','showAdapter','settings')}${suiteLink('Helm controls','Standby, Auto and heading adjustments','showAutopilot','gauge')}${note('Steering commands always require explicit enablement and confirmation from the adapter.')}`;
 case 'Radar':return `${summaryCard('Echo overlay included','Coastline returns, vessels and clutter follow a rotating sweep. All echoes are simulated.','radar')}${suiteLink('Radar echo controls','Gain, sea clutter, range and opacity','showRadarControl','sliders')}${suiteLink('Radar focus','Dedicated radar presentation','showRadar','radar')}${suiteLink('Plugins & adapters','Manage available integration components','showPlugins','layers')}`;
 case 'Display':return `${selectField('Interface scale','displayScale',['100%','125%','150%'],suite.displayScale)}${selectField('Chart layout','displayLayout',['Balanced','Chart focus','Instrument focus'],suite.layout)}<div class="section-label">Light for the moment</div><div class="segment">${['day','dusk','night'].map(t=>`<button data-set-theme="${t}" class="${state.theme===t?'selected':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${button('Apply display preferences','applyDisplay','full primary')}${suiteLink('Personalise instruments','Choose the four primary values','showRail','sliders')}${button('Toggle fullscreen','fullscreen','full')}`;
 case 'System':return systemPanel();
 case 'Help':return helpPanel();
 default:return null;
}}
function systemPanel(){return `<div class="settings-intro"><span class="eyebrow">OPENNAV X · ${suite.updateStatus==='installed'?'0.6.0':'0.5.2'}</span><h3>A complete helm. A cared-for system.</h3><p>Set up, maintain and recover your navigation workspace.</p></div><div class="software-grid">${[['Installation & recovery','Install, repair, roll back or remove','showInstallation','download'],['Updates','Channels, packages and release notes','update','refresh'],['Backups','Export, inspect and restore','showBackups','shield'],['Diagnostics','Health, logs, recording and replay','showDiagnostics','gauge'],['Plugins','Adapters and compatibility','showPlugins','layers'],['Help & guides','Installation guide and everyday tasks','showHelp','info']].map(([a,b,c,d])=>suiteLink(a,b,c,d)).join('')}</div>${suiteLink('About & licenses','Versions, notices and compatibility','showAbout','info')}${suiteLink('Run vessel setup','Vessel, energy, sources and control','welcome','boat')}`;}
function sensorList(){return `<div class="panel-intro"><p>A healthy network starts with a source you can trust.</p>${button(icon('plus')+' Add sensor','addSensor','primary')}</div><div class="source-summary">${tag(suite.sensors.filter(s=>s.status==='Current').length+' CURRENT')}${tag(suite.sensors.length+' CONFIGURED','neutral')}</div>${suite.sensors.length?suite.sensors.map(s=>`<button class="sensor-list-item" data-sensor-id="${s.id}"><span class="sensor-dot ${s.status==='Current'?'':'unavailable'}"></span><span><b>${esc(s.name)}</b><small>${esc(s.signal)} · ${esc(s.transport)} · ${esc(s.priority)}</small></span><span class="sensor-freshness">${s.status}<small>${s.status==='Current'?esc(s.age):'—'}</small></span>${icon('chevron')}</button>`).join(''):`<div class="empty-state">${icon('gauge')}<h3>No sources yet</h3><p>Add a sensor to begin receiving measurements.</p></div>`}${suiteLink('Network health & source loss','Inspect message cadence and test data quality','showHealth','shield')}${note('Device discovery and received readings in this design preview are simulated.')}`;}
function sensorDetails(){const s=suite.sensors.find(s=>s.id===suite.sensorId);if(!s)return '<div class="empty-state">This sensor is no longer configured.</div>';return `<div class="pill-row">${tag(s.status,s.status==='Current'?'':'warning')}${tag(s.transport,'neutral')}</div>${field('Display name','sensorName',s.name)}${selectField('Measurement','sensorSignal',['GPS','Heading','Depth','Wind','Motor','Battery','Tanks','AIS','Rudder','Water temperature'],s.signal)}${selectField('Source precedence','sensorPriority',['Primary','Secondary','Fallback'],s.priority)}${field('Calibration offset','sensorOffset',s.offset,'number','step="0.1"')}${row('Connection',esc(s.endpoint))}${row('Message / PGN',esc(s.pgn))}${row('Update cadence',esc(s.rate))}${row('Freshness',s.status==='Current'?esc(s.age):'Unavailable')}${formError()}<div class="action-row">${button('Save configuration','saveSensor','primary')}${button(s.status==='Current'?'Disconnect':'Reconnect','sensorConnect')}</div>${suiteLink('Calibrate measurement','Inspect a known reference and apply an offset','sensorCalibration','sliders')}${button('Remove sensor','removeSensor','full danger')}`;}
function sensorWizard(){const d=suite.sensorDraft;const steps=['Connection','Discovery','Assignment','Verify'];let body='';if(suite.sensorStep===0){body=`<p class="muted-copy">Choose how this device sends data to the boat’s network.</p><div class="transport-options">${['NMEA 2000','NMEA 0183','Signal K'].map((t,i)=>`<button class="transport-card ${d.transport===t?'selected':''}" data-transport="${t}">${icon(i===0?'layers':i===1?'route':'radar')}<b>${t}</b><small>${['CAN / gateway','Serial / TCP / UDP','Network / WebSocket'][i]}</small>${d.transport===t?icon('check'):''}</button>`).join('')}</div>${field(d.transport==='NMEA 2000'?'Gateway / interface':d.transport==='NMEA 0183'?'Port or network endpoint':'Signal K host','sensorEndpoint',d.endpoint)}${d.transport==='NMEA 0183'?selectField('Baud rate','sensorBaud',['4800','38400','115200'],'38400'):''}${note('Connection details are saved as mock configuration. This page does not contact a real device.')}`;}else if(suite.sensorStep===1){body=`<div class="discovery-state">${icon(suite.sensorError?'info':suite.sensorDiscovery?'check':'radar')}<h3>${suite.sensorError?'No response from the gateway':suite.sensorDiscovery?'Three devices found':'Ready to find your sensors'}</h3><p>${suite.sensorError?'Check the endpoint and try again. Your configuration is retained.':suite.sensorDiscovery?'Select a device or enter its name manually.':'Scan the selected connection for supported measurements.'}</p></div>${button(suite.sensorDiscovery?'Scan again':'Scan for devices','scanSensors','full primary')}${suite.sensorDiscovery?['Multi-sensor gateway','GNSS receiver','Battery monitor'].map((n,i)=>`<button class="discovered-device ${d.device===n?'selected':''}" data-device-name="${n}"><span><b>${n}</b><small>${['Depth · wind · water temperature','GPS · heading · speed','Battery · state of charge'][i]}</small></span>${icon(d.device===n?'check':'plus')}</button>`).join(''):''}<details class="sensor-details"><summary>Manual entry / connection test</summary>${field('Device name','manualSensorName',d.device)}${button('Use manual entry','manualSensor','full')}${button('Preview a connection error','sensorScanError','full')}</details>`;}else if(suite.sensorStep===2){body=`${field('Sensor name','newSensorName',d.name)}${selectField('Measurement','newSensorSignal',['Depth','GPS','Heading','Wind','Motor','Battery','Tanks','AIS','Rudder','Water temperature'],d.signal)}${selectField('Source precedence','newSensorPriority',['Primary','Secondary','Fallback'],d.priority)}${summaryCard('Avoid competing primary sources','Choose Primary only when this device should supply the selected measurement. Existing sources can remain as fallbacks.','info')}`;}else{body=`${summaryCard('Measurement verified','A sample measurement and update cadence were received from the demo source.','check')}<div class="verification-value"><span>${esc(d.signal)}</span><b>${({Depth:'8.4 m',GPS:'58° 20.462′ N',Heading:'041°',Wind:'14.3 kn',Motor:'820 RPM',Battery:'68%',Tanks:'72%',AIS:'4 targets',Rudder:'+2°','Water temperature':'16.8 °C'})[d.signal]}</b><small>SIMULATED READING · AGE 0.5 s</small></div>${row('Device',esc(d.device))}${row('Connection',d.transport)}${row('Priority',d.priority)}${row('Cadence','2 Hz · mock')}`;}return `${wizardProgress(steps,suite.sensorStep)}${body}${formError()}<div class="wizard-footer">${wizardReturn(suite.sensorStep)}${button(suite.sensorStep===3?'Add to sensors':'Continue','sensorNext','primary')}</div>`;}
function wizardProgress(labels,index){return `<ol class="wizard-progress">${labels.map((l,i)=>`<li class="${i===index?'current':i<index?'complete':''}"><span>${i<index?'✓':String(i+1).padStart(2,'0')}</span><b>${l}</b></li>`).join('')}</ol>`;}
function installationPanel(){return `<div class="settings-intro"><span class="eyebrow">SET UP WITH CONFIDENCE</span><h3>From install to first passage.</h3><p>Guided installation with compatibility checks and a recoverable configuration.</p></div>${suiteLink('Installation guide','Requirements, host detection and first launch','installationGuide','info')}${suiteLink('Launch setup wizard','Walk through all installation screens','installer','download')}${suiteLink('Repair installation','Verify and restore application components','repair','refresh')}${suiteLink('Roll back a version','Restore the last verified application','rollback','arrow')}${suiteLink('Application modes','OpenNav X, Legacy and Safe mode','showModes','layers')}${suiteLink('Uninstall OpenNav X','Remove the interface; preserve OpenCPN','uninstall','trash')}${note('This is an interactive installer design. No system files or installed applications are changed.')}`;}
function renderInstaller(){const steps=['Welcome','Detect host','Options','Review','Install','Ready'];let body='';const i=suite.installerStep;if(i===0)body=`<span class="eyebrow mint">A MODERN HELM, ON A TRUSTED FOUNDATION</span><h2>Welcome to OpenNav X.</h2><p class="large-copy">Bring a clearer view to your existing OpenCPN installation. Your charts, routes and original application stay yours.</p><div class="install-checks">${summaryCard('Windows desktop','Reference UI for a 1280 × 800 touchscreen.','check')}${summaryCard('Compatible OpenCPN host','Only known versions and binary hashes are eligible.','shield')}${summaryCard('Space to recover','Create a restore point before making changes.','download')}</div><label class="check-row"><input type="checkbox" id="installTerms" ${suite.installLicense?'checked':''}> I have reviewed the preview installation information.</label>${button('Read installation guide','installationGuide','full')}`;
 else if(i===1)body=`<h2>Find your navigation foundation.</h2><p class="large-copy">Detect the host application and verify its version before continuing.</p>${selectField('Compatibility scenario','installScenario',['supported','unknown version','host missing'],suite.installScenario)}${button('Detect OpenCPN','detectHost','primary full')}${suite.installDetected?`<div class="compatibility-card ${suite.installScenario==='supported'?'':'warning'}">${icon(suite.installScenario==='supported'?'check':'info')}<div><b>${suite.installScenario==='supported'?'Compatible host verified':suite.installScenario==='host missing'?'No host installation found':'This binary is not recognised'}</b><p>${suite.installScenario==='supported'?'OpenCPN · supported reference build · original preserved':'Choose a supported host. An unknown application is never modified.'}</p></div></div>${row('Installation folder','C:\\Program Files\\OpenCPN')}${row('Hash verification',suite.installScenario==='supported'?'Matched · mock manifest':'Not verified')}`:''}`;
 else if(i===2)body=`<h2>Make room for a new perspective.</h2>${field('Installation folder','installPath',suite.installPath)}<div class="install-checks">${['Create OpenNav X shortcut','Create Legacy OpenCPN shortcut','Create Safe Mode shortcut','Back up configuration before installing'].map((t,n)=>`<label class="check-row"><input type="checkbox" data-install-option="${n}" ${suite.installOptions[n]?'checked':''} ${n===3?'disabled':''}>${t}</label>`).join('')}</div>${row('Estimated space','240 MB · example')}${row('Available space','64.2 GB · example')}${note('Chart libraries are reused from the host. They are not copied into configuration backups.')}`;
 else if(i===3)body=`<h2>Ready when you are.</h2>${summaryCard('A recoverable installation','A configuration backup and rollback point come first.','shield')}${row('Destination',esc(suite.installPath))}${row('OpenCPN host','Verified reference version')}${row('Original application','Preserved')}${row('Shortcuts',['OpenNav X','Legacy','Safe Mode'].filter((_,i)=>suite.installOptions[i]).join(' · ')||'None selected')}${row('After installation','Self-test → vessel setup')}${note('Selecting Install runs a simulated installation sequence only.')}`;
 else if(i===4)body=`<h2>${suite.installProgress===100?'Application files verified.':'Preparing your new helm…'}</h2><p class="large-copy">${['Verifying the package','Creating a recovery point','Installing interface components','Registering shortcuts','Running the post-install self-test','Complete'][Math.min(5,Math.floor(suite.installProgress/20))]}</p><div class="progress-track"><i style="width:${suite.installProgress}%"></i></div><div class="progress-caption"><b>${suite.installProgress}%</b><span>SIMULATED INSTALLATION</span></div><div class="install-log">${['Signed package and SHA-256 checked','Configuration backup created','Original host retained','Interface components installed','Shortcut and startup checks passed'].map((s,n)=>`<p class="${suite.installProgress>n*20?'done':''}">${suite.installProgress>n*20?'✓':'○'} ${s}</p>`).join('')}</div>`;
 else body=`<div class="success-hero">${icon('check')}<span class="eyebrow mint">INSTALLATION COMPLETE</span><h2>Your next passage starts here.</h2><p>The simulated installation and self-test completed successfully.</p></div>${row('Host compatibility','Passed')}${row('Configuration access','Passed')}${row('Chart directories','Preserved')}${row('Hardware control','Off by default')}${row('Recovery shortcut','Ready')}`;
 return serviceLayout('INSTALLATION',steps,i,body,i===4&&suite.installBusy?'<button class="btn danger" data-action="cancelInstallation" data-context-return>Cancel installation</button>':wizardReturn(i,i>=4)+button(i===5?'Set up your vessel':i===3?'Install OpenNav X':'Continue','installerNext','primary'));}
function serviceLayout(label,steps,index,body,footer){return `<div class="service-header"><span class="tag neutral">DESIGN PREVIEW · NO SYSTEM CHANGES</span></div><div class="service-layout"><aside class="service-step-list"><div class="service-mark">${icon('boat')}<span>${label}</span></div>${steps.map((s,i)=>`<div class="${i===index?'current':i<index?'complete':''}"><span>${i<index?'✓':String(i+1).padStart(2,'0')}</span><b>${s}</b></div>`).join('')}<p>Your original OpenCPN installation is preserved.</p></aside><section class="service-content">${body}${formError()}<div class="service-footer">${footer}</div></section></div>`;}
function setupView(){const d=suite.setupDraft,i=suite.setupStep,steps=['Your vessel','Display','Sources','Energy','Helm control','Ready'];let body='';if(i===0)body=`<h2>Let’s make this helm yours.</h2><p class="large-copy">A few vessel details give your forecasts the right context.</p>${field('Vessel name','setupName',d.name)}<div class="form-grid">${field('Draft · m','setupDraft',d.draft,'number','min="0.1" step="0.1"')}${field('Safety depth · m','setupSafety',d.safety,'number','min="0.1" step="0.1"')}</div>`;
 else if(i===1)body=`<h2>Comfortable at every hour.</h2>${selectField('Distance & speed','setupUnits',['Nautical','Metric'],d.units)}${selectField('Initial display mode','setupTheme',['day','dusk','night'],d.theme)}${summaryCard('Adapts to your display','The helm adjusts to compact desktop and touch layouts.','gauge')}`;
 else if(i===2)body=`<h2>Bring your boat into view.</h2><p class="large-copy">Review detected sources, or add another connection.</p>${row('GPS / heading','Current · mock')}${row('Depth / wind','Current · mock')}${row('Battery / motor','Current · mock')}${row('Water tank','No source assigned')}${suiteLink('Add a sensor','Open the connection wizard; return here afterwards','addSensor','plus')}${suiteLink('Inspect all sources','Review freshness and priority','showSensors','gauge')}`;
 else if(i===3)body=`<h2>A reserve for the unexpected.</h2>${field('Usable battery capacity · kWh','setupCapacity',d.capacity,'number','min="1" step="0.1"')}${field('Minimum reserve · %','setupReserve',d.reserve,'number','min="5" max="90"')}${summaryCard('Calibrate after real passages','Start with a configured estimate; improve it with representative vessel runs.','bolt')}`;
 else if(i===4)body=`<h2>You have the helm.</h2>${summaryCard('Control remains off','Detecting an autopilot never enables steering. Control must be explicitly enabled later.','lock')}${row('Adapter','Generic heading adapter · mock')}${row('Standby / Auto','Available in preview')}${row('Track / Wind','Requires capability verification')}${row('Command acknowledgement','Required')}`;
 else body=`<div class="success-hero">${icon('check')}<span class="eyebrow mint">READY TO EXPLORE</span><h2>Welcome aboard, ${esc(d.name)}.</h2><p>Your vessel profile is ready for the next passage.</p></div>${row('Draft / safety depth',d.draft+' m / '+d.safety+' m')}${row('Energy',d.capacity+' kWh · '+d.reserve+'% reserve')}${row('Sources',suite.sensors.length+' configured · mock')}${row('Autopilot control','Off')}`;
 return serviceLayout('VESSEL SETUP',steps,i,body,wizardReturn(i)+button(i===5?'Open your helm':'Continue','setupNext','primary'));}
function updatePanel(){const s=suite.updateStatus;return `<div class="version-hero">${icon('refresh')}<span class="eyebrow">SOFTWARE UPDATE</span><h3>${s==='installed'?'You’re up to date.':s==='cached'?'Verified and ready.':s==='available'?'A clearer view is ready.':'Keep your helm current.'}</h3><p>Installed: ${s==='installed'?'0.6.0':'0.5.2'} · ${suite.updateChannel}</p></div>${selectField('Release channel','updateChannel',['Stable','Beta'],suite.updateChannel)}${['available','cached','installed'].includes(s)?`<div class="release-card"><span>${tag('0.6.0 · '+suite.updateChannel)}</span><h4>Built around your next passage.</h4><ul><li>Refined configuration and return navigation</li><li>Clearer source-quality states</li><li>Radar echo overlay presentation</li></ul></div>`:''}${s==='checking'||s==='downloading'?'<div class="progress-track indeterminate"><i></i></div>':''}${row('Manifest','Signed · simulated verification')}${row('Compatibility','Checked before install')}${row('Recovery','Automatic rollback on failed startup')}${row('Offline startup','Last verified version remains available')}${s==='idle'?button('Check now','checkUpdate','full primary'):s==='available'?button('Download update','downloadUpdate','full primary'):s==='cached'?button('Install verified update','installVerifiedUpdate','full primary'):s==='installed'?button('View installation history','updateHistory','full'):''}${note('Release and package activity are simulated. No software is downloaded or installed.')}`;}
function backupPanel(){return `<p class="muted-copy">Carry your setup to another computer, or return to a known configuration.</p>${Object.entries(suite.backupSelection).map(([k,v])=>`<label class="check-row"><input type="checkbox" data-backup-part="${k}" ${v?'checked':''}>${{settings:'Display & navigation preferences',vessel:'Vessel & energy calibration',sensors:'Sensors & adapter preferences',routes:'Mock routes & waypoints'}[k]}</label>`).join('')}<div class="excluded-note">${icon('lock')} Chart files and licenses are excluded.</div><div class="action-row">${button('Create & export backup','createBackup','primary')}${button('Import backup file','restore')}</div><div class="section-label">Recovery points · this session</div>${suite.snapshots.length?suite.snapshots.map((b,i)=>`<button class="suite-link" data-backup-index="${i}"><span class="suite-link-icon">${icon('shield')}</span><span><b>${esc(b.name)}</b><small>${esc(b.time)} · mock configuration</small></span>${icon('chevron')}</button>`).join(''):'<div class="empty-state compact">No recovery points yet. Create a backup to inspect and restore it.</div>'}${button('Preview restoring a sample backup','sampleBackup','full')}`;}
function diagnosticsPanel(){return `<div class="segment">${['Overview','Logs','Sessions'].map(t=>`<button data-diagnostic-tab="${t}" class="${suite.diagnosticTab===t?'selected':''}">${t}</button>`).join('')}</div>${suite.diagnosticTab==='Overview'?`${row('Application','OpenNav X '+(suite.updateStatus==='installed'?'0.6.0':'0.5.2'))}${row('Host','OpenCPN · mock compatible host')}${row('Build','design-suite-20260928')}${row('Display',innerWidth+' × '+innerHeight+' · '+devicePixelRatio+'×')}${row('Navigation bus','Selected source messages present')}${row('Radar adapter',state.radar?'Simulated sweep active':'Standby')}${row('Autopilot adapter',state.apEnabled?'Preview enabled':'Read-only')}${suiteLink('Inspect source health','PGNs, rates, freshness and precedence','showHealth','gauge')}`:suite.diagnosticTab==='Logs'?`<div class="log-toolbar"><span>${tag('MOCK SESSION','neutral')}</span>${button('Export log','exportLog')}</div><div class="log-console"><p><time>11:48:00</time> INFO · workspace loaded</p><p><time>11:48:01</time> INFO · compatible chart host found</p><p><time>11:48:02</time> INFO · ${suite.sensors.length} source profiles loaded</p><p><time>11:48:03</time> INFO · hardware control disabled</p><p><time>11:49:00</time> ${state.gpsLost?'WARN · GPS source unavailable':'INFO · navigation source current'}</p><p><time>11:49:01</time> ${state.batteryStale?'WARN · battery data stale':'INFO · battery source current'}</p></div>`:`${summaryCard(state.recording?'Recording a bounded session':'Reproduce a problem without the boat','Capture an illustrative session, then inspect replay and dropout states.','gauge')}${row('Capture limit','5 minutes / 20 MB · concept')}${row('Current mode',state.replay?'REPLAY · technical test':'Mock navigation')}${button(state.recording?'Stop & export session':'Start session recording','record','full primary')}${button(state.replay?'Exit replay':'Open replay session','suiteReplay','full')}${suiteLink('Reproduce source loss','GPS dropout and stale battery states','showHealth','info')}`}${button(icon('download')+' Export diagnostic bundle','exportDiagnostics','full primary')}${note('The exported bundle contains only prototype state and mock values. No credentials or real device records are collected.')}`;}
const guides={installation:{title:'Installation guide',steps:[['Before you begin','Close navigation work, check the supported host version and confirm a recoverable configuration backup.'],['Find the host','The setup wizard detects OpenCPN and checks the known version and hash. Unknown binaries are never modified.'],['Choose the workspace','Select the interface folder and shortcuts. Existing charts, plugins and shared routes remain available.'],['Verify and install','Review the signed manifest, package hash and compatibility result, then create the recovery point.'],['First launch','Run the self-test, configure the vessel and verify source freshness. Steering control stays off.'],['If something goes wrong','Use Safe Mode or repair. Roll back to the last verified application/configuration pair. Uninstall preserves the original host.']]},sensors:{title:'Connect a sensor',steps:[['Choose a transport','Use the device’s supported NMEA 2000 gateway, serial/network NMEA 0183 connection, or Signal K endpoint.'],['Discover and assign','Choose the device, assign its measurement and set its source priority.'],['Verify the signal','Inspect its age, message cadence and sample value. A connected gateway does not prove every measurement is valid.'],['Calibrate','Use a known reference and apply a vessel-appropriate offset. Retain the original reading for diagnostics.']]},navigation:{title:'Plan and navigate',steps:[['Build a passage','Select Passage, plot chart positions, undo if needed and give the route a name.'],['Review the route','Inspect depth coverage and the route corridor before activation. All values here are mock examples.'],['Read your horizon','Upcoming turns, traffic and arrival energy appear together. Open any event for context.'],['Return where you came from','Each page has one return action: Back to its parent or Close to its workspace. Wizard footers use Cancel, Back or Done for the current step.']]},radar:{title:'Read the radar demo',steps:[['Start the sweep','Enable the echo overlay or radar focus. The prototype generates returns from its fictional coastline and targets.'],['Tune the image','Gain adjusts echo strength; sea and rain controls suppress their respective clutter.'],['Choose range','Near and far ranges change which returns are visible. An overlay opacity control keeps the chart readable.'],['Keep the distinction clear','This is synthetic radar imagery. It is not a recording, a live feed or a verified radar/AIS correlation.']]},recovery:{title:'Back up and recover',steps:[['Create a recovery point','Export the chosen settings, vessel, sensors and mock route data. Charts are excluded.'],['Inspect before restoring','Review the backup version and included sections. Restore only compatible, validated settings.'],['Choose a recovery path','Repair restores components, rollback returns to a known version, and Safe Mode disables SmartNav/hardware controls.']]}};
function helpPanel(){const q=suite.helpQuery.toLowerCase();return `<div class="settings-intro"><span class="eyebrow">A HAND WHEN YOU NEED IT</span><h3>Find your way.</h3><p>Practical guides, recovery paths and support information.</p></div>${suiteLink('Chart symbols & seamarks','Meaning, appearance and chart-symbol reference','showSymbols','chart')}<input class="search-field" id="helpSearch" placeholder="Search guides…" aria-label="Search help" value="${esc(suite.helpQuery)}"><div id="helpResults">${Object.entries(guides).filter(([,g])=>g.title.toLowerCase().includes(q)).map(([id,g])=>`<button class="suite-link" data-guide-id="${id}"><span class="suite-link-icon">${icon('info')}</span><span><b>${g.title}</b><small>${g.steps.length} steps · read in the app</small></span>${icon('chevron')}</button>`).join('')||'<div class="empty-state compact">No guides match. Try “sensor” or “radar”.</div>'}</div>${suiteLink('Keyboard & touch','Shortcuts, gestures and return navigation','shortcuts','gauge')}${suiteLink('Prepare a support bundle','Review and export local mock diagnostics','showDiagnostics','download')}${suiteLink('About & licenses','Build information and third-party notices','showAbout','info')}`;}
function chartsPanel(){return `<div class="panel-intro"><p>Manage chart availability before you leave the dock.</p>${button(icon('plus')+' Add chart package','addChart','primary')}</div>${suite.charts.map(c=>`<button class="suite-link" data-chart-pack="${c.id}"><span class="suite-link-icon">${icon('chart')}</span><span><b>${esc(c.name)}</b><small>${c.format} · ${c.edition} · ${c.size}</small></span><span class="tag ${c.status==='Ready'?'':'warning'}">${c.status}</span></button>`).join('')}${row('Storage used',suite.charts.reduce((sum,c)=>sum+parseFloat(c.size),0)+' MB · illustrative')}${row('Offline availability','Installed packages retained')}${note('Only chart-package metadata is demonstrated. Real chart licenses and files remain managed by OpenCPN.')}`;}
function renderSuitePanel(){let title,body,eyebrow='CONFIGURATION';switch(state.panel){
 case 'chartSymbol':title=selectedChartSymbol()?.name||'Chart symbol';eyebrow='CHART OBJECT · DEMO';body=chartSymbolPanel();break;
 case 'symbolDetail':{const g=seamarkGuide.find(g=>g.id===suite.symbolGuide);title=g?g.en:(symbolById.get(suite.symbolId)?.code||'Symbol');eyebrow='SYMBOL ATLAS';body=symbolDetailBody();break;}
 case 'radarControl':title='Radar echo overlay';eyebrow='SITUATIONAL AWARENESS';body=radarControls()+suiteLink('Radar focus','Open the dedicated echo display','showRadar','radar');break;
 case 'system':title='Software centre';body=systemPanel();break;
 case 'sensors':title='Your sensor network';body=sensorList();break;
 case 'sensor':title=suite.sensors.find(s=>s.id===suite.sensorId)?.signal+' source';body=sensorDetails();break;
 case 'sensorAdd':title='Add a sensor';eyebrow='CONNECTION WIZARD';body=sensorWizard();break;
 case 'installation':title='Install. Maintain. Recover.';eyebrow='SOFTWARE LIFECYCLE';body=installationPanel();break;
 case 'updates':title='Software updates';body=updatePanel();break;
 case 'backups':title='A way back, always.';body=backupPanel();break;
 case 'diagnostics':title='System diagnostics';body=diagnosticsPanel();break;
 case 'help':title='Help & guides';body=helpPanel();break;
 case 'guide':{const g=guides[suite.guide];title=g.title;eyebrow='IN-APP GUIDE';body=`<div class="guide-steps">${g.steps.map(([a,b],i)=>`<section><span>${String(i+1).padStart(2,'0')}</span><div><h3>${a}</h3><p>${b}</p></div></section>`).join('')}</div>${suite.guide==='installation'&&state.view!=='installer'?button('Open setup wizard','installer','full primary'):suite.guide==='sensors'?button('Add a sensor','addSensor','full primary'):suite.guide==='radar'?button('Open radar controls','showRadarControl','full primary'):''}`;break;}
 case 'charts':title='Charts & coverage';body=chartsPanel();break;
 case 'chartPack':{const c=suite.charts.find(c=>c.id===suite.packId);title=c.name;body=`<div class="chart-preview-art">${icon('chart')}<span>${esc(c.region)}</span></div>${row('Format',c.format)}${row('Edition',c.edition)}${row('Package size',c.size)}${row('License','Managed by chart provider · mock')}${row('State',c.status)}${button(c.status==='Ready'?'Verify package':'Update package metadata','verifyChart','full primary')}${button('Remove chart package','removeChart','full danger')}`;break;}
 case 'alarms':title='The right alert, in time.';body=`<p class="muted-copy">Set meaningful thresholds for your vessel and passage.</p><div class="form-grid">${field('AIS CPA · nm','alarmCpa',suite.alarm.cpa,'number','min="0.1" step="0.1"')}${field('AIS TCPA · min','alarmTcpa',suite.alarm.tcpa,'number','min="1"')}</div><div class="form-grid">${field('Minimum depth · m','alarmDepth',suite.alarm.depth,'number','min="0.1" step="0.1"')}${field('Energy reserve · %','alarmEnergy',suite.alarm.energy,'number','min="5" max="90"')}</div>${toggle('Audible alerts','alarmSound',suite.alarm.sound)}${toggle('GPS loss alerts','alarmGps',suite.alarm.gps)}${toggle('Anchor alerts','alarmAnchor',suite.alarm.anchor)}${formError()}${button('Save thresholds','saveAlarms','full primary')}${summaryCard('Critical alerts remain visible','Acknowledging a critical alert does not hide an unresolved condition.','bell')}${suiteLink('Review active alerts','Open the notification centre','showAlerts','bell')}`;break;
 case 'plugins':title='Connected capabilities';body=`<p class="muted-copy">Keep the host’s plugin ecosystem within reach.</p>${suite.plugins.map((p,i)=>`<div class="plugin-card"><div><b>${p.name}</b><small>Compatible · mock manifest</small></div><button class="toggle" role="switch" aria-label="${p.name}" aria-checked="${p.state}" data-plugin-id="${i}"></button></div>`).join('')}${row('Compatibility status','Reference adapters verified')}${suiteLink('Adapter configuration','Choose a heading adapter and capability model','showAdapter','settings')}${note('These switches alter the prototype configuration only; no plugins are installed or executed.')}`;break;
 case 'adapter':title='Autopilot adapter';body=`${selectField('Adapter selection','adapterChoice',['Auto detect','Generic NMEA heading adapter','Signal K autopilot adapter'],suite.adapter)}${selectField('Connection','adapterConnection',['NMEA 2000 gateway','NMEA 0183 serial','Signal K endpoint'],suite.adapterConnection)}${row('Status / heading readback','Supported · mock')}${row('Standby / Auto','Supported · mock')}${row('Track / Wind','Not yet verified')}${field('Acknowledgement timeout · seconds','adapterTimeout',suite.adapterTimeout,'number','min="1" max="10"')}${button('Test & save adapter','saveAdapter','full primary')}${suiteLink('Open helm controls','Control remains off until explicitly enabled','showAutopilot','gauge')}`;break;
 case 'about':title='OpenNav X';eyebrow='A CLEARER COURSE';body=`<div class="about-mark">${icon('boat')}<span>opennav<b>x</b></span></div>${row('Version',(suite.updateStatus==='installed'?'0.6.0':'0.5.2')+' · design suite')}${row('Build','2026.09.28')}${row('Host','OpenCPN · illustrative compatibility')}${row('Runtime','Offline HTML / mock data')}${row('Display',innerWidth+' × '+innerHeight)}<details class="sensor-details"><summary>Third-party notices & chart licenses</summary><p>This prototype contains original interface code and illustrative chart artwork, plus the OpenCPN chart-symbol library (GPL-2.0). The design package includes its source files, license and provenance in vendor/opencpn; see SYMBOLS.md. The production installer must display its actual dependency license manifest. Chart-provider licenses remain separate from configuration backups.</p></details>${suiteLink('Support diagnostics','Export a local bundle before requesting help','showDiagnostics','download')}`;break;
 case 'library':title='Your passages & places';body=`${suiteLink(esc(state.routeName),state.waypoints.length+' waypoints · '+(state.routeActive?'active':'saved'),'showRoute','route')}${button('Plot a new passage','newRoute','full primary')}<div class="section-label">Saved places</div>${state.custom.length?state.custom.map((w,i)=>`<button class="suite-link" data-library-point="${i}">${icon('pin')}<span><b>${esc(w.name)}</b><small>${coordinateText(w)}</small></span>${icon('chevron')}</button>`).join(''):'<div class="empty-state compact">No saved places yet. Add a waypoint directly on the chart.</div>'}<div class="action-row">${button('Import sample GPX','importGpx')}${button('Export passage GPX','exportGpx')}</div>${suiteLink('Track recording','Inspect or replay a recorded mock session','showDiagnostics','gauge')}`;break;
 default:return false;
 }setPanel(eyebrow,title,body);return true;}
function renderSuiteView(){if(state.view==='symbols')$('#fullView').innerHTML=renderSymbolAtlas();else if(state.view==='installer')$('#fullView').innerHTML=renderInstaller();else if(state.view==='setup')$('#fullView').innerHTML=setupView();else if(state.view==='maintenance')$('#fullView').innerHTML=maintenanceView();else return false;hydrate();updateNavigation();return true;}
function maintenanceView(){const task=suite.maintenance,i=suite.maintenanceStep;return serviceLayout(task.toUpperCase(),['Review','Apply','Complete'],i,i===0?`<h2>${task} OpenNav X.</h2><p class="large-copy">${task==='Uninstall'?'Remove the modern interface while keeping the original OpenCPN application, charts and navigation data.':task==='Rollback'?'Return to the last verified application and configuration backup.':'Verify application components and replace missing or damaged files.'}</p>${summaryCard('A recovery point comes first','Your current configuration is retained before the simulated operation.','shield')}${row('Original OpenCPN','Preserved')}${row('Chart libraries','Preserved')}${row('Operation',task+' · simulated')}`:i===1?`<h2>${task} in progress…</h2><div class="progress-track indeterminate"><i></i></div><p class="large-copy">Verifying the recovery point and application state.</p>`:`<div class="success-hero">${icon('check')}<h2>${task} preview complete.</h2><p>The original host and navigation data remain available. No real system files were changed.</p></div>${row('Verification','Passed · simulation')}${row('Configuration recovery','Available')}`,(i===2?wizardReturn(i,true):'<button class="btn" data-action="back" data-context-return>'+(i===1?'Cancel operation':'Cancel')+'</button>')+(i===0?button('Preview '+task.toLowerCase(),'runMaintenance',task==='Uninstall'?'danger':'primary'):''));}
function nextWizard(property,render){pushContext();suite[property]++;render();updateNavigation();(state.panel?$('#drawerBody'):$('#fullView')).scrollTop=0;}
function downloadText(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function suiteBackup(){const data={format:'OpenNavX-design-backup',version:2,mock:true,createdAt:new Date().toISOString(),sections:structuredClone(suite.backupSelection),chartsIncluded:false};if(data.sections.vessel)data.vessel={name:state.vessel,draft:state.draftDepth,safetyDepth:state.safetyDepth,capacity:state.capacity,reserve:state.reserve};if(data.sections.settings)data.settings={theme:state.theme,units:state.units,alarm:structuredClone(suite.alarm),preferences:structuredClone(suite.preferences)};if(data.sections.sensors)data.sensors={profiles:structuredClone(suite.sensors),adapter:suite.adapter};if(data.sections.routes)data.routes={waypoints:structuredClone(state.custom),passage:structuredClone(state.waypoints),name:state.routeName,destination:state.destination};return data;}
function restoreReview(data){validateBackup(data);suite.restoreDraft=data;openModal('Review before restoring.',`<p>This backup contains mock configuration. Inspect its contents before applying it.</p>${row('Format','OpenNav X · v'+data.version)}${row('Included sections',Object.entries(data.sections||{vessel:true,settings:true,routes:true}).filter(([,v])=>v).map(([k])=>k).join(', '))}${row('Charts / licenses','Not included')}<div class="callout"><b>Your current setup will be saved</b>A recovery point is created before applying this configuration.</div><div class="action-row">${button('Back','back')}${button('Restore configuration','confirmRestore','primary')}</div>`,'BACKUP & RESTORE');}
const suiteActions={back:goBack,showSensors:()=>openPanel('sensors'),showInstallation:()=>openPanel('installation'),showBackups:()=>openPanel('backups'),showDiagnostics:()=>openPanel('diagnostics'),showHelp:()=>openPanel('help'),showAbout:()=>openPanel('about'),showCharts:()=>openPanel('charts'),showAlarms:()=>openPanel('alarms'),showLibrary:()=>openPanel('library'),showPlugins:()=>openPanel('plugins'),showAdapter:()=>openPanel('adapter'),showRadarControl:()=>openPanel('radarControl'),showAlerts:()=>openPanel('alerts'),showRoute:()=>openPanel('route'),
 addSensor:()=>{suite.sensorStep=0;suite.sensorDiscovery=false;suite.sensorError=false;openPanel('sensorAdd');},
 scanSensors:()=>{suite.sensorError=false;suite.sensorDiscovery=true;renderPanel();},sensorScanError:()=>{suite.sensorDiscovery=false;suite.sensorError=true;renderPanel();},manualSensor:()=>{const name=$('#manualSensorName').value.trim();if(!name)return invalid('Enter a device name.');suite.sensorDraft.device=name;suite.sensorDiscovery=true;renderPanel();},
 sensorNext:()=>{const d=suite.sensorDraft;if(suite.sensorStep===0){const endpoint=$('#sensorEndpoint').value.trim();if(!endpoint)return invalid('Enter a gateway, port or host.');d.endpoint=endpoint;}else if(suite.sensorStep===1&&!suite.sensorDiscovery)return invalid('Scan and choose a device, or use manual entry.');else if(suite.sensorStep===2){if(!$('#newSensorName').value.trim())return invalid('Give this sensor a name.');d.name=$('#newSensorName').value.trim();d.signal=$('#newSensorSignal').value;d.priority=$('#newSensorPriority').value;}if(suite.sensorStep<3){nextWizard('sensorStep',renderPanel);return;}if(d.priority==='Primary')suite.sensors.filter(s=>s.signal===d.signal&&s.priority==='Primary').forEach(s=>s.priority='Fallback');const id='source-'+Date.now();suite.sensors.push({id,name:d.name,signal:d.signal,transport:d.transport,endpoint:d.endpoint,priority:d.priority,status:'Current',age:'.5 s',rate:'2 Hz',pgn:'Sample message',offset:0});exitFlow();toast(d.name+' added · simulated measurement verified');},
 saveSensor:()=>{const s=suite.sensors.find(s=>s.id===suite.sensorId),name=$('#sensorName').value.trim(),offset=+$('#sensorOffset').value;if(!name||!Number.isFinite(offset)||Math.abs(offset)>100)return invalid('Enter a name and a calibration offset between −100 and 100.');const signal=$('#sensorSignal').value,priority=$('#sensorPriority').value;if(priority==='Primary')suite.sensors.filter(p=>p.id!==s.id&&p.signal===signal&&p.priority==='Primary').forEach(p=>p.priority='Fallback');Object.assign(s,{name,signal,priority,offset});renderPanel();toast('Sensor configuration saved');},
 sensorConnect:()=>{const s=suite.sensors.find(s=>s.id===suite.sensorId);s.status=s.status==='Current'?'Disconnected':'Current';if(s.id==='gps'){state.gpsLost=s.status!=='Current';if(!state.gpsLost&&state.critical==='GPS signal lost')state.critical=null;}if(s.id==='battery')state.batteryStale=s.status!=='Current';syncStatus();if(state.view==='energy')renderView();renderPanel();},
 removeSensor:()=>{const s=suite.sensors.find(s=>s.id===suite.sensorId);openModal('Remove this source?',`<p>${esc(s.name)} will be removed from the mock configuration. Its measurement becomes unavailable until a fallback is selected.</p><div class="action-row">${button('Keep sensor','back')}${button('Remove sensor','confirmRemoveSensor','danger')}</div>`,'SENSOR CONFIGURATION');},
 confirmRemoveSensor:()=>{if(suite.sensorId==='gps')state.gpsLost=true;if(suite.sensorId==='battery')state.batteryStale=true;suite.sensors=suite.sensors.filter(s=>s.id!==suite.sensorId);closeModal();syncStatus();goBack();toast('Sensor removed from configuration');},
 sensorCalibration:()=>{const s=suite.sensors.find(s=>s.id===suite.sensorId);openModal('Calibrate '+esc(s.signal.toLowerCase()),`${row('Source',esc(s.name))}${field('Offset from known reference','calibrationOffset',s.offset,'number','step="0.1"')}${note('The offset is stored as a design preference; no physical sensor is changed.')}<div class="action-row">${button('Back','back')}${button('Apply offset','applyCalibration','primary')}</div>`,'MEASUREMENT CALIBRATION');},applyCalibration:()=>{const n=+$('#calibrationOffset').value;if(!Number.isFinite(n)||Math.abs(n)>100)return toast('Enter an offset between −100 and 100.');suite.sensors.find(s=>s.id===suite.sensorId).offset=n;closeModal();renderPanel();toast('Calibration offset saved');},
 saveNavigation:()=>{const n=+$('#routeCorridor').value;if(n<.05||n>2)return toast('Choose a corridor between 0.05 and 2 nm.');state.units=$('#navUnits').value;suite.preferences.route=$('#routePreference').value;suite.preferences.corridor=n;toast('Navigation preferences saved');},
 saveAlarms:()=>{const cpa=+$('#alarmCpa').value,tcpa=+$('#alarmTcpa').value,depth=+$('#alarmDepth').value,energy=+$('#alarmEnergy').value;if(cpa<=0||tcpa<1||depth<=0||energy<5||energy>90)return invalid('Use positive traffic/depth thresholds and a reserve between 5% and 90%.');Object.assign(suite.alarm,{cpa,tcpa,depth,energy});state.safetyDepth=depth;state.reserve=energy;syncStatus();toast('Alarm thresholds saved');},alarmSound:()=>{suite.alarm.sound=!suite.alarm.sound;renderPanel();},alarmGps:()=>{suite.alarm.gps=!suite.alarm.gps;renderPanel();},alarmAnchor:()=>{suite.alarm.anchor=!suite.alarm.anchor;renderPanel();},
 applyDisplay:()=>{suite.displayScale=$('#displayScale').value;suite.layout=$('#displayLayout').value;$('#app').dataset.uiScale=suite.displayScale;$('#app').dataset.layout=suite.layout;toast('Display preferences applied');},
 saveAdapter:()=>{const timeout=+$('#adapterTimeout').value;if(timeout<1||timeout>10)return toast('Choose a timeout between 1 and 10 seconds.');suite.adapter=$('#adapterChoice').value;suite.adapterTimeout=timeout;suite.adapterConnection=$('#adapterConnection').value;state.apEnabled=false;state.apMode='Standby';state.apPending=false;clearTimeout(pendingTimer);syncStatus();toast('Adapter settings saved · mock readback passed · control off');},
 installationGuide:()=>{suite.guide='installation';openPanel('guide');},installer:()=>{suite.installBusy=false;suite.installRun=(suite.installRun||0)+1;suite.installerStep=0;suite.installDetected=false;suite.installLicense=false;fullView('installer');},
 installerNext:()=>{const i=suite.installerStep;if(i===0){suite.installLicense=$('#installTerms').checked;if(!suite.installLicense)return invalid('Review the preview installation information before continuing.');}if(i===1&&(!suite.installDetected||suite.installScenario!=='supported'))return invalid('A verified, compatible host is required. Detect a supported host before continuing.');if(i===2){suite.installOptions=$$('[data-install-option]').map(el=>el.checked);suite.installPath=$('#installPath').value.trim();if(!suite.installPath)return invalid('Choose an installation folder.');}if(i===3){suite.installProgress=0;suite.installBusy=true;const run=suite.installRun=(suite.installRun||0)+1;nextWizard('installerStep',renderView);const tick=()=>{if(!suite.installBusy||run!==suite.installRun)return;suite.installProgress+=20;if(suite.installProgress>=100)suite.installBusy=false;if(state.view==='installer'&&suite.installerStep===4)renderView();if(suite.installProgress<100&&suite.installBusy)setTimeout(tick,450);else suite.installBusy=false;};setTimeout(tick,450);return;}if(i===5){suite.installed=true;suiteActions.welcome();return;}if(!suite.installBusy)nextWizard('installerStep',renderView);},
 detectHost:()=>{suite.installScenario=$('#installScenario').value;suite.installDetected=true;renderView();},cancelInstallation:()=>openModal('Cancel this installation?',`<p>The simulated setup stops and restores its recovery point.</p><div class="action-row">${button('Continue installation','back')}${button('Cancel & roll back','confirmCancelInstall','danger')}</div>`,'SETUP'),confirmCancelInstall:()=>{suite.installBusy=false;suite.installProgress=0;closeModal();exitFlow();toast('Setup cancelled · recovery point restored');},
 welcome:()=>{suite.setupStep=0;suite.setupDraft={name:state.vessel,draft:state.draftDepth,safety:state.safetyDepth,capacity:state.capacity,reserve:state.reserve,units:state.units,theme:state.theme};fullView('setup');},
 setupNext:()=>{const d=suite.setupDraft,i=suite.setupStep;if(i===0){const name=$('#setupName').value.trim(),draft=+$('#setupDraft').value,safety=+$('#setupSafety').value;if(!name||draft<=0||safety<draft)return invalid('Enter a vessel name and a safety depth at least as deep as the draft.');Object.assign(d,{name,draft,safety});}if(i===1){d.units=$('#setupUnits').value;d.theme=$('#setupTheme').value;}if(i===3){const capacity=+$('#setupCapacity').value,reserve=+$('#setupReserve').value;if(capacity<1||reserve<5||reserve>90)return invalid('Enter capacity ≥ 1 kWh and a reserve from 5% to 90%.');Object.assign(d,{capacity,reserve});}if(i===5){Object.assign(state,{vessel:d.name,draftDepth:d.draft,safetyDepth:d.safety,capacity:d.capacity,reserve:d.reserve,units:d.units,apEnabled:false,apMode:'Standby'});setTheme(d.theme);showChart();syncChart();syncStatus();toast('Vessel setup complete');return;}nextWizard('setupStep',renderView);},
 repair:()=>startMaintenance('Repair'),rollback:()=>startMaintenance('Rollback'),uninstall:()=>startMaintenance('Uninstall'),runMaintenance:()=>{suite.maintenanceBusy=true;const run=suite.maintenanceRun=(suite.maintenanceRun||0)+1;nextWizard('maintenanceStep',renderView);setTimeout(()=>{if(run!==suite.maintenanceRun||!suite.maintenanceBusy)return;suite.maintenanceBusy=false;suite.maintenanceStep=2;if(state.view==='maintenance')renderView();},1200);},maintenanceDone:exitFlow,
 showModes:()=>openModal('Choose your workspace.',`<p>Production mode changes use a controlled restart and shared navigation data.</p>${row('Current workspace','OpenNav X')}${suiteLink('Legacy OpenCPN','Original host interface and advanced settings','legacy','layers')}${suiteLink('Safe Mode','Recovery without SmartNav or hardware control','safe','shield')}`,'APPLICATION MODES'),
 update:()=>openPanel('updates'),checkUpdate:()=>{suite.updateStatus='checking';renderPanel();setTimeout(()=>{suite.updateStatus='available';if(state.panel==='updates')renderPanel();},650);},downloadUpdate:()=>{suite.updateStatus='downloading';renderPanel();setTimeout(()=>{suite.updateStatus='cached';if(state.panel==='updates')renderPanel();},850);},installVerifiedUpdate:()=>openModal('Install the verified update?',`${row('Package','0.6.0 · '+suite.updateChannel)}${row('Integrity','Signed manifest + hash · mock pass')}${row('Recovery','Application and configuration backup')}${note('This runs an interface simulation. No executable is installed.')}<div class="action-row">${button('Back','back')}${button('Preview update','finishSuiteUpdate','primary')}</div>`,'VERIFIED UPDATE'),finishSuiteUpdate:()=>{suite.updateStatus='installed';closeModal();renderPanel();toast('Update preview completed · startup self-test passed');},updateHistory:()=>openModal('Installation history',`${row('0.6.0','Current · mock self-test passed')}${row('0.5.2','Previous · rollback available')}${button('Open recovery options','recoveryFromUpdate','full')}`,'SOFTWARE'),recoveryFromUpdate:()=>{closeModal();openPanel('installation');},
 createBackup:()=>{if(!Object.values(suite.backupSelection).some(Boolean))return toast('Select at least one section to export.');const data=suiteBackup();suite.snapshots.unshift({name:'Manual recovery point',time:new Date().toLocaleTimeString(),data});download('OpenNavX-design-backup.json',data);renderPanel();toast('Backup created and exported');},sampleBackup:()=>{if(!Object.values(suite.backupSelection).some(Boolean))return toast('Select at least one section to preview.');const d=suiteBackup();if(d.vessel)d.vessel.name='Reptil · restored';restoreReview(d);},
 confirmRestore:()=>{const d=suite.restoreDraft;validateBackup(d);suite.snapshots.unshift({name:'Before restore',time:new Date().toLocaleTimeString(),data:suiteBackup()});if(d.version===1){Object.assign(state,{vessel:d.vessel,capacity:d.capacity,reserve:d.reserve,draftDepth:d.draft,safetyDepth:d.safetyDepth,custom:d.waypoints});setTheme(d.theme);}else{if(d.vessel)Object.assign(state,{vessel:d.vessel.name,draftDepth:d.vessel.draft,safetyDepth:d.vessel.safetyDepth,capacity:d.vessel.capacity,reserve:d.vessel.reserve});if(d.settings){state.units=d.settings.units;Object.assign(suite.alarm,d.settings.alarm);Object.assign(suite.preferences,d.settings.preferences);setTheme(d.settings.theme);}if(d.sensors){suite.sensors=structuredClone(d.sensors.profiles);suite.adapter=d.sensors.adapter;}if(d.routes){state.custom=structuredClone(d.routes.waypoints);state.waypoints=structuredClone(d.routes.passage);state.routeName=d.routes.name;state.destination=d.routes.destination;state.routeCustomized=true;}}state.apEnabled=false;state.apMode='Standby';state.apPending=false;clearTimeout(pendingTimer);closeModal();syncChart();syncStatus();if(state.panel)renderPanel();toast('Configuration restored · prior setup saved');},
 exportLog:()=>downloadText('OpenNavX-mock-session.log','OpenNav X — mock diagnostic session\n11:48:00 INFO Workspace loaded\n11:48:03 INFO Hardware control disabled\n11:49:00 '+(state.gpsLost?'WARN GPS unavailable':'INFO GPS current')+'\n','text/plain'),suiteReplay:()=>{state.replay=!state.replay;syncStatus();renderPanel();},
 addChart:()=>openModal('Add chart coverage.',`<p>Select an example chart package to preview validation and library management.</p>${field('Package name','chartPackageName','Stockholm archipelago')}${selectField('Chart format','chartPackageFormat',['Vector ENC','Raster BSB','MBTiles'],'Vector ENC')}${summaryCard('Licenses stay with the chart','The production importer verifies format and provider license before indexing.','lock')}<div class="action-row">${button('Back','back')}${button('Validate & add example','commitChart','primary')}</div>`,'CHART LIBRARY'),commitChart:()=>{const name=$('#chartPackageName').value.trim();if(!name)return toast('Enter a package name.');suite.charts.push({id:'pack-'+Date.now(),name,format:$('#chartPackageFormat').value,edition:'2026.09',size:'120 MB',status:'Ready',region:'Illustrative coverage'});closeModal();renderPanel();toast('Example package validated and added');},verifyChart:()=>{suite.charts.find(c=>c.id===suite.packId).status='Ready';renderPanel();toast('Package metadata verified · mock license available');},removeChart:()=>openModal('Remove this chart package?',`<p>Remove this example from the library. Other chart packages and navigation data remain available.</p><div class="action-row">${button('Keep package','back')}${button('Remove package','confirmRemoveChart','danger')}</div>`,'CHART LIBRARY'),confirmRemoveChart:()=>{suite.charts=suite.charts.filter(c=>c.id!==suite.packId);closeModal();goBack();},
 importGpx:()=>openModal('Import a passage',`${row('Sample file','Evening-cove.gpx')}${row('Contents','1 route · 3 waypoints')}${row('Validation','Compatible GPX structure · example')}${button('Import sample route','commitGpx','full primary')}`,'PASSAGE LIBRARY'),commitGpx:()=>{state.custom.push({name:'Evening cove',x:620,y:395},{name:'Sheltered approach',x:650,y:415},{name:'Harbour entrance',x:690,y:450});closeModal();syncChart();renderPanel();toast('Sample GPX waypoints imported');},exportGpx:()=>downloadText('OpenNavX-mock-passage.gpx','<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="OpenNav X design preview" xmlns="http://www.topografix.com/GPX/1/1"><rte><name>'+esc(state.routeName)+'</name>'+state.waypoints.map(w=>'<rtept lat="'+(58.32+(630-w.y)/60000).toFixed(6)+'" lon="'+(16.75+w.x/9900).toFixed(6)+'"><name>'+esc(w.name)+'</name></rtept>').join('')+'</rte></gpx>','application/gpx+xml'),
 shortcuts:()=>openModal('A familiar way back.',`${row('Escape / Alt + ←','Use the current return action')}${row('Tab / Shift + Tab','Move keyboard focus')}${row('Enter / Space','Activate focused control')}${row('Drag / wheel / pinch','Pan and zoom chart')}${row('Long-press / right-click','Chart position sheet')}${row('Close ×','Dismiss the active context')}`,'KEYBOARD & TOUCH')};
function startMaintenance(task){suite.maintenanceBusy=false;suite.maintenanceRun=(suite.maintenanceRun||0)+1;suite.maintenance=task;suite.maintenanceStep=0;fullView('maintenance');}
Object.assign(actions,suiteActions);
function handleSuiteClick(b){if(handleSymbolClick(b))return true;if(b.dataset.sensorId){suite.sensorId=b.dataset.sensorId;openPanel('sensor');return true;}if(b.dataset.transport){suite.sensorDraft.transport=b.dataset.transport;suite.sensorDraft.endpoint=b.dataset.transport==='NMEA 2000'?'can0':b.dataset.transport==='NMEA 0183'?'COM4':'vessel.local:3000';renderPanel();return true;}if(b.dataset.deviceName){suite.sensorDraft.device=b.dataset.deviceName;renderPanel();return true;}if(b.dataset.guideId){suite.guide=b.dataset.guideId;openPanel('guide');return true;}if(b.dataset.chartPack){suite.packId=b.dataset.chartPack;openPanel('chartPack');return true;}if(b.dataset.pluginId!==undefined){suite.plugins[+b.dataset.pluginId].state=!suite.plugins[+b.dataset.pluginId].state;renderPanel();return true;}if(b.dataset.backupIndex!==undefined){restoreReview(suite.snapshots[+b.dataset.backupIndex].data);return true;}if(b.dataset.diagnosticTab){suite.diagnosticTab=b.dataset.diagnosticTab;renderPanel();return true;}if(b.dataset.libraryPoint!==undefined){const i=+b.dataset.libraryPoint;pointForm(state.custom[i],i);return true;}return false;}
document.addEventListener('input',e=>{if(e.target.id==='helpSearch'){suite.helpQuery=e.target.value;const old=$('#helpResults');const wrap=document.createElement('div');wrap.innerHTML=helpPanel();old.replaceWith(wrap.querySelector('#helpResults'));}});
document.addEventListener('change',e=>{if(e.target.id==='updateChannel'){suite.updateChannel=e.target.value;suite.updateStatus='idle';renderPanel();}if(e.target.dataset.backupPart)suite.backupSelection[e.target.dataset.backupPart]=e.target.checked;if(e.target.id==='installScenario'){suite.installScenario=e.target.value;suite.installDetected=false;}});
